// ─── index.js ─────────────────────────────────────────────
// Run with:  node --env-file=.env.local index.js

const key = process.env.OPENAI_API_KEY

if (!key) {
  console.error('\nMissing the OPENAI_API_KEY key.')
  console.error('Check three things, in this order:')
  console.error(' 1. That the .env.local file exists in this same folder.')
  console.error(' 2. That it contains OPENAI_API_KEY=something, with no spaces around the equals sign.')
  console.error(' 3. That you started it with: node --env-file=.env.local index.js\n')
  process.exit(1)
}

console.log('Node', process.version)
console.log('Key loaded correctly:', key.slice(0, 7) + '...')
console.log('All set.\n')


